function csv(s){let rows=[],row=[],v='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=''}else if(c==='\n'&&!q){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v=''}else v+=c}if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row)}let h=rows.shift();return rows.filter(r=>r.length===h.length).map(r=>Object.fromEntries(h.map((k,i)=>[k.replace(/^\uFEFF/,''),r[i]])))}
async function unzip(ab){let v=new DataView(ab),b=new Uint8Array(ab),out={};let e=b.length-22;while(e>=0&&v.getUint32(e,true)!==0x06054b50)e--;if(e<0)throw Error('Invalid ZIP');let p=v.getUint32(e+16,true),n=v.getUint16(e+10,true);for(let i=0;i<n;i++){let method=v.getUint16(p+10,true),size=v.getUint32(p+20,true),nl=v.getUint16(p+28,true),el=v.getUint16(p+30,true),cl=v.getUint16(p+32,true),local=v.getUint32(p+42,true),name=new TextDecoder().decode(b.slice(p+46,p+46+nl));let start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true),data=b.slice(start,start+size);if(name.endsWith('.txt')){if(method===8)data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());else if(method!==0)throw Error('Unsupported ZIP');out[name]=csv(new TextDecoder().decode(data))}p+=46+nl+el+cl}return out}
export async function load({offlineOnly=false}={}){let url=BASE+'gtfs/gtfs.zip',r,cached=false;try{if(offlineOnly)throw Error('Offline');r=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Schedule HTTP '+r.status);if(typeof caches!=='undefined'){try{let c=await caches.open('tuka-schedule');let headers=new Headers(r.headers);headers.set('x-tuka-downloaded-at',new Date().toISOString());await c.put(url,new Response(r.clone().body,{status:r.status,headers}))}catch{/* Browsing still works if storage is full. */}}}catch(e){if(typeof caches!=='undefined')r=await caches.match(url);if(!r)throw e;cached=true}let f=await unzip(await r.arrayBuffer());let db={stops:f['stops.txt'].map(s=>({...s,id:s.stop_id,name:s.stop_name,lat:+s.stop_lat,lon:+s.stop_lon})),routes:new Map(f['routes.txt'].map(r=>[r.route_id,r])),trips:new Map(f['trips.txt'].map(t=>[t.trip_id,t])),times:new Map(),byStop:new Map(),cached,downloadedAt:r.headers.get('x-tuka-downloaded-at')||(!cached?new Date().toISOString():null),calendar:f['calendar.txt']||[],exceptions:f['calendar_dates.txt']||[],info:f['feed_info.txt']?.[0]||{},shapes:new Map()};for(let s of f['stop_times.txt']){let t={...s,seq:+s.stop_sequence,seconds:seconds(s.departure_time||s.arrival_time),arrivalSeconds:seconds(s.arrival_time||s.departure_time)};if(!db.times.has(s.trip_id))db.times.set(s.trip_id,[]);db.times.get(s.trip_id).push(t);if(!db.byStop.has(s.stop_id))db.byStop.set(s.stop_id,[]);db.byStop.get(s.stop_id).push(t)}for(let t of db.times.values())t.sort((a,b)=>a.seq-b.seq);for(let p of f['shapes.txt']||[]){if(!db.shapes.has(p.shape_id))db.shapes.set(p.shape_id,[]);db.shapes.get(p.shape_id).push([+p.shape_pt_lon,+p.shape_pt_lat,+p.shape_pt_sequence])}for(let p of db.shapes.values())p.sort((a,b)=>a[2]-b[2]);return db}
function fields(b){let p=0,out={};function varint(){let v=0n,shift=0n;while(p<b.length){let c=b[p++];v|=BigInt(c&127)<<shift;if(!(c&128))return Number(BigInt.asIntN(64,v));shift+=7n}throw Error('Invalid protobuf')}while(p<b.length){let tag=varint(),k=tag>>3,w=tag&7,val;if(w===0)val=varint();else if(w===2){let n=varint();val=b.slice(p,p+n);p+=n}else if(w===1){p+=8;continue}else if(w===5){val=new DataView(b.buffer,b.byteOffset+p,4).getFloat32(0,true);p+=4}else throw Error('Unsupported protobuf');(out[k]??=[]).push(val)}return out}
const str=b=>b?new TextDecoder().decode(b):'';const first=(f,k)=>f[k]?.[0];
function readEvent(raw){if(!raw)return null;const f=fields(raw);let delay=first(f,1);if(delay>2147483647)delay-=4294967296;return {time:first(f,2),delay};}
async function mainRealtime(){let r=await fetch(BASE+'gtfsrt/tripupdates.pb',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('Realtime HTTP '+r.status);let f=fields(new Uint8Array(await r.arrayBuffer())),head=fields(first(f,1)),timestamp=first(head,3),updates=new Map(),vehicles=[],alerts=[];for(let raw of f[2]||[]){let entity=fields(raw);if(first(entity,2))continue;if(first(entity,5))alerts.push(decodeAlert(first(entity,5),fields));if(first(entity,4)){let v=fields(first(entity,4)),td=first(v,1)?fields(first(v,1)):{},p=first(v,2)?fields(first(v,2)):{},descriptor=first(v,8)?fields(first(v,8)):{};if(first(p,1)!=null&&first(p,2)!=null)vehicles.push({id:str(first(descriptor,1))||str(first(entity,1)),label:str(first(descriptor,2)),tripId:str(first(td,1)),routeId:str(first(td,5)),date:str(first(td,3)),lat:first(p,1),lon:first(p,2),bearing:first(p,3),timestamp:first(v,5)||timestamp,seq:first(v,3),stopId:str(first(v,7))})}if(!first(entity,3))continue;let u=fields(first(entity,3)),trip=fields(first(u,1)),id=str(first(trip,1)),start=str(first(trip,3)),rel=first(trip,4);if(rel===3)updates.set(id+'|*|'+start,{tripRelationship:rel});for(let rawstop of u[2]||[]){let s=fields(rawstop),event=first(s,2)||first(s,3),ev=event?fields(event):{},delay=first(ev,1);if(delay>2147483647)delay-=4294967296;updates.set(id+'|'+str(first(s,4))+'|'+start,{time:first(ev,2),delay,arrival:readEvent(first(s,2)),departure:readEvent(first(s,3)),relationship:first(s,5),tripRelationship:rel,seq:first(s,1)})}}return {timestamp,alertTimestamp:timestamp,alerts,updates,vehicles:vehicles.map(v=>({...v,source:'Modeshift'})),modeshift:true}}
export async function realtime(db,stopId,onPrimary){const code=db?.stops.find(s=>s.id===stopId)?.stop_code;const [main,extra]=await Promise.allSettled([mainRealtime().then(r=>{if(onPrimary&&Math.abs(Date.now()/1000-r.timestamp)<120)onPrimary({...r,sources:{modeshift:true,skopska:false}});return r;}),db?additional(code):Promise.reject(Error('No network'))]);if(main.status==='rejected'&&extra.status==='rejected')throw Error('Live data unavailable');let rt=main.status==='fulfilled'?main.value:{timestamp:0,updates:new Map(),vehicles:[],modeshift:false};if(Math.abs(Date.now()/1000-rt.timestamp)>120){rt.updates.clear();rt.vehicles=[];rt.modeshift=false;}const day=serviceDay();if(extra.status==='fulfilled'&&db)rt=mergeAdditional(db,rt,extra.value,day,active(db,day));else rt.sources={modeshift:!!rt.modeshift,skopska:false};return rt}
export function seconds(s){return s.split(':').reduce((a,n)=>a*60+ +n,0)}
function scheduledDepartures(db,rt,id,now=Date.now(),limit=16,options={}){let list=[];const lookback=Math.ceil((db.byStop.get(id)||[]).reduce((n,p)=>Math.max(n,p.seconds),86400)/86400);for(let offset=-lookback;offset<=1;offset++){let day=serviceDay(offset,now),ids=active(db,day);for(let s of db.byStop.get(id)||[]){let trip=db.trips.get(s.trip_id);if(!ids.has(trip.service_id)||s.pickup_type==='1')continue;let predicted=prediction(rt,s.trip_id,id,day,now);if(predicted?.relationship===1||predicted?.tripRelationship===3)continue;let scheduled=day.midnight+s.seconds*1000;let estimate=eventTime(predicted,'departure',scheduled),time=estimate.time;if(time<now-20000||time>now+(options.horizonHours||4)*3600000)continue;list.push({trip,s,route:db.routes.get(trip.route_id),time,scheduled,live:estimate.live,source:predicted?.source||'Modeshift',day})}}return list.sort((a,b)=>a.time-b.time).slice(0,limit)}
export function departures(db,rt,id,now=Date.now(),limit=16,options={}){return mergeArrivals(db,Math.abs(now-Date.now())<120000?rt:null,id,scheduledDepartures(db,rt,id,now,Math.max(200,limit),options),now,serviceDay(0,now)).slice(0,limit)}
